#!/usr/bin/env python
"""One-time setup. Writes every project file into the right folder.

Put this file in your repo root and run it once:

    python setup_project.py

It creates src/, scripts/, configs/, tests/ and fills them. Existing files
are overwritten, so rerunning resets the project to a known state.

File contents are stored compressed and base64-encoded below, purely so
this stays a single self-contained file. Once the real files are written
and committed you can delete this script.
"""

import base64
import zlib
from pathlib import Path

FILES = {
    'README.md': "",
    'requirements.txt': "eNorqKxMzM2xszXTM+AqSMxLSSy2szUCsrmUFdwDQhXy83Iq9RT88ksU8lJTU1JTFNLyixRKMlIVcvOTsxWSEpOzU/NSFKBiJanFJcV6QJ1lOTm5drYGehZ6plwA2RweRA==",
    'configs/models.yaml': "",
    'scripts/fetch_dataset.py': "",
    'scripts/run_prompt_stability.py': "",
    'scripts/make_handlabel_sheet.py': "",
    'scripts/combine_results.py': "",
    'src/cot_faith/__init__.py': "eNoDAAAAAAE=",
    'src/cot_faith/data.py': "",
    'src/cot_faith/prompts.py': "",
    'src/cot_faith/parsing.py': "",
    'src/cot_faith/metrics.py': "",
    'src/cot_faith/generate.py': "",
    'tests/test_parsing.py': "",
}


def main() -> None:
    root = Path(__file__).resolve().parent
    for rel, payload in FILES.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(zlib.decompress(base64.b64decode(payload)))
        print(f"wrote {rel}")
    (root / "results").mkdir(exist_ok=True)
    print(f"\n{len(FILES)} files written. Next:")
    print("  python tests/test_parsing.py")
    print("  python scripts/run_prompt_stability.py --model llama3b --backend mock")


if __name__ == "__main__":
    main()
